<?php
namespace App\Http\Controllers\Api;
use App\Domain\Media\Models\Media; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str; use App\Http\Controllers\Controller;
class MediaController extends Controller { public function upload(Request $r){$d=$r->validate(['file'=>'required|file|mimes:jpg,jpeg,png,webp,gif,svg,pdf,mp4|max:10240','alt_text'=>'nullable|string|max:255','is_public'=>'boolean']);$f=$d['file'];$disk=config('filesystems.default','local');$name=Str::uuid().'.'.$f->extension();$path=$f->storeAs('web-media', $name, $disk);$m=Media::create(['disk'=>$disk,'path'=>$path,'original_name'=>$f->getClientOriginalName(),'mime_type'=>$f->getMimeType(),'size'=>$f->getSize(),'alt_text'=>$d['alt_text']??null,'is_public'=>$d['is_public']??false]);return response()->json($m,201);} public function destroy(Media $media){abort_unless($media->is_public || request()->user()->hasPermission('web.media.delete'),403);Storage::disk($media->disk)->delete($media->path);$media->delete();return response()->noContent();} public function url(Media $media){return ['url'=>$media->is_public?Storage::disk($media->disk)->url($media->path):(method_exists(Storage::disk($media->disk),'temporaryUrl')?Storage::disk($media->disk)->temporaryUrl($media->path,now()->addMinutes(10)):null)];} }
